/**
 * Distributed Tracing Service
 * Tracks requests across services with OpenTelemetry integration
 */

import { Logger } from '../../shared/logger';
import type { D1Database, D1PreparedStatement } from '@cloudflare/workers-types';

export interface TraceContext {
  traceId: string;
  spanId: string;
  parentSpanId?: string;
  flags: number;
  baggage?: Record<string, string>;
}

export interface Span {
  traceId: string;
  spanId: string;
  parentSpanId?: string;
  operationName: string;
  serviceName: string;
  startTime: number;
  endTime?: number;
  duration?: number;
  status: 'ok' | 'error' | 'cancelled';
  attributes: Record<string, any>;
  events: SpanEvent[];
  links: SpanLink[];
  error?: Error;
}

export interface SpanEvent {
  name: string;
  timestamp: number;
  attributes?: Record<string, any>;
}

export interface SpanLink {
  traceId: string;
  spanId: string;
  attributes?: Record<string, any>;
}

export interface TracingConfig {
  serviceName: string;
  samplingRate: number;
  maxSpansPerTrace: number;
  exportInterval: number;
  enableAutoInstrumentation: boolean;
}

export // TODO: Consider splitting TracingService into smaller, focused classes
class TracingService {
  private logger: Logger;
  private db?: D1Database;
  private config: TracingConfig;
  private activeSpans = new Map<string, Span>();
  private completedSpans: Span[] = [];
  private exportInterval?: NodeJS.Timeout;
  private spanIdCounter = 0;

  constructor(config: Partial<TracingConfig> = {}, db?: D1Database) {
    this.logger = new Logger();
    this.db = db;
    this.config = {
      serviceName: 'agent-system',
      samplingRate: 1.0,
      maxSpansPerTrace: 1000,
      exportInterval: 5000,
      enableAutoInstrumentation: true,
      ...config
    };

    this.startExporter();
  }

  /**
   * Create a new trace context
   */
  createTraceContext(parentContext?: TraceContext): TraceContext {
    const traceId = parentContext?.traceId || this.generateTraceId();
    const spanId = this.generateSpanId();

    return {
      traceId,
      spanId,
      parentSpanId: parentContext?.spanId,
      flags: this.shouldSample() ? 1 : 0,
      baggage: parentContext?.baggage || {}
    };
  }

  /**
   * Start a new span
   */
  startSpan(
    operationName: string,
    context?: TraceContext,
    attributes: Record<string, any> = {}
  ): Span {
    const traceContext = context || this.createTraceContext();

    const span: Span = {
      traceId: traceContext.traceId,
      spanId: traceContext.spanId,
      parentSpanId: traceContext.parentSpanId,
      operationName,
      serviceName: this.config.serviceName,
      startTime: Date.now(),
      status: 'ok',
      attributes: {
        ...attributes,
        'service.name': this.config.serviceName,
        'span.kind': attributes.kind || 'internal'
      },
      events: [],
      links: []
    };

    this.activeSpans.set(span.spanId, span);

    this.logger.debug('Span started', {
      traceId: span.traceId,
      spanId: span.spanId,
      operation: operationName
    });

    return span;
  }

  /**
   * End a span
   */
  endSpan(spanId: string, error?: Error): void {
    const span = this.activeSpans.get(spanId);
    if (!span) {
      this.logger.warn('Attempted to end non-existent span', { spanId });
      return;
    }

    span.endTime = Date.now();
    span.duration = span.endTime - span.startTime;

    if (error) {
      span.status = 'error';
      span.error = error;
      span.attributes['error'] = true;
      span.attributes['error.type'] = error.name;
      span.attributes['error.message'] = error.message;
      if (error.stack) {
        span.attributes['error.stack'] = error.stack;
      }
    }

    this.activeSpans.delete(spanId);
    this.completedSpans.push(span);

    this.logger.debug('Span ended', {
      traceId: span.traceId,
      spanId: span.spanId,
      duration: span.duration,
      status: span.status
    });

    // Check if we should export
    if (this.completedSpans.length >= 100) {
      this.exportSpans().catch((error: any) => {
        this.logger.error('Failed to export spans', error);
      });
    }
  }

  /**
   * Add event to span
   */
  addSpanEvent(spanId: string, name: string, attributes?: Record<string, any>): void {
    const span = this.activeSpans.get(spanId);
    if (!span) return;

    span.events.push({
      name,
      timestamp: Date.now(),
      attributes
    });
  }

  /**
   * Add link to span
   */
  addSpanLink(spanId: string, link: SpanLink): void {
    const span = this.activeSpans.get(spanId);
    if (!span) return;

    span.links.push(link);
  }

  /**
   * Set span attributes
   */
  setSpanAttributes(spanId: string, attributes: Record<string, any>): void {
    const span = this.activeSpans.get(spanId);
    if (!span) return;

    Object.assign(span.attributes, attributes);
  }

  /**
   * Instrument async function with tracing
   */
  instrument<T extends (...args: any[]) => Promise<any>>(
    fn: T,
    operationName: string,
    extractContext?: (args: Parameters<T>) => TraceContext | undefined
  ): T {
    return (async (...args: Parameters<T>) => {
      const context = extractContext ? extractContext(args) : undefined;
      const span = this.startSpan(operationName, context);

      try {
        const result = await fn(...args);
        this.endSpan(span.spanId);
        return result;
      } catch (error: any) {
        this.endSpan(span.spanId, error as Error);
        throw error;
      }
    }) as T;
  }

  /**
   * Create child span
   */
  createChildSpan(parentSpan: Span, operationName: string): Span {
    return this.startSpan(
      operationName,
      {
        traceId: parentSpan.traceId,
        spanId: this.generateSpanId(),
        parentSpanId: parentSpan.spanId,
        flags: 1
      }
    );
  }

  /**
   * Extract trace context from headers
   */
  extractContext(headers: Headers | Record<string, string>): TraceContext | undefined {
    const traceParent = this.getHeader(headers, 'traceparent');
    if (!traceParent) return undefined;

    // Parse W3C Trace Context format
    const parts = traceParent.split('-');
    if (parts.length !== 4) return undefined;

    const [version, traceId, spanId] = parts;

    // Parse baggage
    const baggageHeader = this.getHeader(headers, 'baggage');
    const baggage: Record<string, string> = {};

    if (baggageHeader) {
      baggageHeader.split(',').forEach((item: any) => {
        const [key, value] = item.trim().split('=');
        if (key && value) {
          baggage[key] = decodeURIComponent(value);
        }
      });
    }

    return {
      traceId,
      spanId,
      // flags: parseInt(flags, 16),
      baggage
    };
  }

  /**
   * Inject trace context into headers
   */
  injectContext(context: TraceContext, headers: Headers | Record<string, string>): void {
    // W3C Trace Context format
    const traceParent = `00-${context.traceId}-${context.spanId}-${context.flags.toString(16).padStart(2, '0')}`;

    if (headers instanceof Headers) {
      headers.set('traceparent', traceParent);

      if (context.baggage && Object.keys(context.baggage).length > 0) {
        const baggageItems = Object.entries(context.baggage)
          .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
          .join(',');
        headers.set('baggage', baggageItems);
      }
    } else {
      headers['traceparent'] = traceParent;

      if (context.baggage && Object.keys(context.baggage).length > 0) {
        const baggageItems = Object.entries(context.baggage)
          .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
          .join(',');
        headers['baggage'] = baggageItems;
      }
    }
  }

  /**
   * Get trace graph for a trace ID
   */
  async getTraceGraph(traceId: string): Promise<{
    spans: Span[];
    rootSpan?: Span;
    tree: Map<string, Span[]>;
  }> {
    const spans = await this.getTraceSpans(traceId);

    // Build parent-child relationship tree
    const tree = new Map<string, Span[]>();
    let rootSpan: Span | undefined;

    for (const span of spans) {
      if (!span.parentSpanId) {
        rootSpan = span;
      } else {
        const siblings = tree.get(span.parentSpanId) || [];
        siblings.push(span);
        tree.set(span.parentSpanId, siblings);
      }
    }

    return { spans, rootSpan, tree };
  }

  /**
   * Get all spans for a trace
   */
  private async getTraceSpans(traceId: string): Promise<Span[]> {
    const spans: Span[] = [];

    // Get from active spans
    for (const span of this.activeSpans.values()) {
      if (span.traceId === traceId) {
        spans.push(span);
      }
    }

    // Get from completed spans
    for (const span of this.completedSpans) {
      if (span.traceId === traceId) {
        spans.push(span);
      }
    }

    // Get from database if available
    if (this.db) {
      try {
        const result = await this.db.prepare(`
          SELECT * FROM trace_spans
          WHERE trace_id = ?
          ORDER BY start_time ASC
        `).bind(traceId).all();

        const dbSpans = (result.results || []).map((row: any) => this.deserializeSpan(row));
        spans.push(...dbSpans);
      } catch (error: any) {
        this.logger.error('Failed to fetch spans from database', error);
      }
    }

    return spans;
  }

  /**
   * Export spans to storage
   */
  private async exportSpans(): Promise<void> {
    if (this.completedSpans.length === 0) return;

    const spansToExport = [...this.completedSpans];
    this.completedSpans = [];

    if (!this.db) {
      this.logger.warn('No database configured for span export');
      return;
    }

    try {
      const batch: D1PreparedStatement[] = [];

      for (const span of spansToExport) {
        batch.push(
          this.db.prepare(`
            INSERT OR REPLACE INTO trace_spans (
              trace_id, span_id, parent_span_id, operation_name,
              service_name, start_time, end_time, duration,
              status, attributes, events, links
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          `).bind(
            span.traceId,
            span.spanId,
            span.parentSpanId || null,
            span.operationName,
            span.serviceName,
            span.startTime,
            span.endTime || null,
            span.duration || null,
            span.status,
            JSON.stringify(span.attributes),
            JSON.stringify(span.events),
            JSON.stringify(span.links)
          )
        );
      }

      await this.db.batch(batch);

      this.logger.info('Exported spans', { count: spansToExport.length });

    } catch (error: any) {
      this.logger.error('Failed to export spans', error);
      // Re-add spans to be exported later
      this.completedSpans.push(...spansToExport);
    }
  }

  /**
   * Deserialize span from database
   */
  private deserializeSpan(row: any): Span {
    return {
      traceId: row.trace_id,
      spanId: row.span_id,
      parentSpanId: row.parent_span_id || undefined,
      operationName: row.operation_name,
      serviceName: row.service_name,
      startTime: row.start_time,
      endTime: row.end_time || undefined,
      duration: row.duration || undefined,
      status: row.status,
      attributes: JSON.parse(row.attributes || '{}'),
      events: JSON.parse(row.events || '[]'),
      links: JSON.parse(row.links || '[]')
    };
  }

  /**
   * Generate trace ID
   */
  private generateTraceId(): string {
    // 32 hex characters (128 bits)
    const buffer = new Uint8Array(16);
    crypto.getRandomValues(buffer);
    return Array.from(buffer)
      .map((b: any) => b.toString(16).padStart(2, '0'))
      .join('');
  }

  /**
   * Generate span ID
   */
  private generateSpanId(): string {
    // 16 hex characters (64 bits)
    const buffer = new Uint8Array(8);
    crypto.getRandomValues(buffer);
    return Array.from(buffer)
      .map((b: any) => b.toString(16).padStart(2, '0'))
      .join('');
  }

  /**
   * Check if should sample
   */
  private shouldSample(): boolean {
    return Math.random() < this.config.samplingRate;
  }

  /**
   * Get header value
   */
  private getHeader(headers: Headers | Record<string, string>, name: string): string | undefined {
    if (headers instanceof Headers) {
      return headers.get(name) || undefined;
    }
    return headers[name];
  }

  /**
   * Start exporter interval
   */
  private startExporter(): void {
    this.exportInterval = setInterval(() => {
      this.exportSpans().catch((error: any) => {
        this.logger.error('Export interval failed', error);
      });
    }, this.config.exportInterval) as any;
  }

  /**
   * Get metrics
   */
  getMetrics(): {
    activeSpans: number;
    completedSpans: number;
    totalExported: number;
  } {
    return {
      activeSpans: this.activeSpans.size,
      completedSpans: this.completedSpans.length,
      totalExported: 0 // Would track this separately
    };
  }

  /**
   * Shutdown tracing
   */
  async shutdown(): Promise<void> {
    if (this.exportInterval) {
      clearInterval(this.exportInterval);
    }

    // Export remaining spans
    await this.exportSpans();

    // End all active spans
    for (const [spanId] of this.activeSpans) {
      this.endSpan(spanId, new Error('Tracing shutdown'));
    }

    this.logger.info('Tracing service shutdown');
  }
}

/**
 * Trace context propagation utilities
 */
export class TraceContextPropagator {
  /**
   * Create context for Cloudflare Workers
   */
  static fromCloudflareRequest(request: Request): TraceContext | undefined {
    const tracingService = new TracingService();
    return tracingService.extractContext(request.headers);
  }

  /**
   * Add context to fetch request
   */
  static addToFetch(url: string, init: RequestInit, context: TraceContext): RequestInit {
    const headers = new Headers(init.headers || {});
    const tracingService = new TracingService();
    tracingService.injectContext(context, headers);

    return {
      ...init,
      headers
    };
  }
}

/**
 * Database schema for traces
 */
export const TRACE_SCHEMA = `
CREATE TABLE IF NOT EXISTS trace_spans (
  trace_id TEXT NOT NULL,
  span_id TEXT NOT NULL,
  parent_span_id TEXT,
  operation_name TEXT NOT NULL,
  service_name TEXT NOT NULL,
  start_time INTEGER NOT NULL,
  end_time INTEGER,
  duration INTEGER,
  status TEXT NOT NULL,
  attributes TEXT,
  events TEXT,
  links TEXT,

  PRIMARY KEY (trace_id, span_id),
  INDEX idx_trace_spans_trace (trace_id),
  INDEX idx_trace_spans_time (start_time DESC),
  INDEX idx_trace_spans_operation (operation_name),
  INDEX idx_trace_spans_status (status) WHERE status = 'error'
);
`;

/**
 * Company Knowledge Agent
 * Learns company website, products, brand guidelines and enforces compliance
 * Target Quality Score: 95/100
 */

import type { D1Database, VectorizeIndex } from '@cloudflare/workers-types';
import type { AgentTask, BusinessContext, AgentResult, AgentConfig, HealthStatus } from './types';
import { Logger } from '../../shared/logger';
import { CorrelationId } from '../../shared/security-utils';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface KnowledgeSource {
  id: string;
  businessId: string;
  sourceName: string;
  sourceType: 'website' | 'api' | 'document' | 'rss_feed' | 'knowledge_base' | 'manual_entry';
  sourceUrl: string;
  scrapingConfig: ScrapingConfig;
  status: 'active' | 'inactive' | 'error' | 'rate_limited';
}

export interface ScrapingConfig {
  maxDepth: number;
  followExternal: boolean;
  rateLimit: number; // requests per second
  includePatterns: string[];
  excludePatterns: string[];
  contentSelectors: {
    title?: string;
    content?: string;
    metadata?: string;
  };
}

export interface CompanyKnowledge {
  id: string;
  businessId: string;
  contentType:
    | 'product'
    | 'service'
    | 'pricing'
    | 'policy'
    | 'faq'
    | 'blog_post'
    | 'documentation'
    | 'brand_guidelines';
  title: string;
  content: string;
  summary: string;
  keywords: string[];
  sourceUrl: string;
  verified: boolean;
  accuracyScore: number;
  freshnessScore: number;
}

export interface BrandVoice {
  tone: 'formal' | 'casual' | 'professional' | 'friendly' | 'technical';
  characteristics: string[];
  doList: string[];
  dontList: string[];
  examplePhrases: string[];
  prohibitedWords: string[];
}

export interface WebScrapeResult {
  url: string;
  title: string;
  content: string;
  links: string[];
  metadata: Record<string, string>;
  scrapedAt: string;
  success: boolean;
  error?: string;
}

// ============================================================================
// COMPANY KNOWLEDGE AGENT
// ============================================================================

export class CompanyKnowledgeAgent {
  public readonly id = 'company-knowledge-agent';
  public readonly name = 'Company Knowledge Learning Agent';
  public readonly type = 'specialized' as const;
  public readonly version = '1.0.0';

  public readonly capabilities = [
    'website_scraping',
    'product_learning',
    'brand_voice_analysis',
    'faq_generation',
    'guideline_extraction',
    'competitor_awareness',
    'knowledge_validation',
    'content_recommendation',
    'knowledge_refresh',
    'compliance_checking'
  ];

  public readonly departments = ['marketing', 'sales', 'support', 'product'];
  public readonly tags = ['knowledge', 'learning', 'scraping', 'brand', 'compliance'];
  public readonly maxConcurrency = 10; // Lower for web scraping
  public readonly costPerCall = 0.005;

  private logger: Logger;
  private db: D1Database;
  private anthropicApiKey?: string;
  private openaiApiKey?: string;
  private vectorizeIndex?: VectorizeIndex;

  // Rate limiting for polite scraping
  private readonly scrapeDelay = 1000; // 1 second between requests
  private lastScrapeTime = 0;

  constructor(env: {
    DB_MAIN: D1Database;
    ANTHROPIC_API_KEY?: string;
    OPENAI_API_KEY?: string;
    VECTORIZE_INDEX?: VectorizeIndex;
  }) {
    this.logger = new Logger();
    this.db = env.DB_MAIN;
    this.anthropicApiKey = env.ANTHROPIC_API_KEY;
    this.openaiApiKey = env.OPENAI_API_KEY;
    this.vectorizeIndex = env.VECTORIZE_INDEX;
  }

  async execute(task: AgentTask, context: BusinessContext): Promise<AgentResult> {
    const startTime = Date.now();

    try {
      let result: any;

      // Route to appropriate capability handler
      switch (task.capability) {
        case 'website_scraping':
          result = await this.handleWebsiteScraping(task, context);
          break;
        case 'product_learning':
          result = await this.handleProductLearning(task, context);
          break;
        case 'brand_voice_analysis':
          result = await this.handleBrandVoiceAnalysis(task, context);
          break;
        case 'faq_generation':
          result = await this.handleFAQGeneration(task, context);
          break;
        case 'guideline_extraction':
          result = await this.handleGuidelineExtraction(task, context);
          break;
        case 'competitor_awareness':
          result = await this.handleCompetitorAwareness(task, context);
          break;
        case 'knowledge_validation':
          result = await this.handleKnowledgeValidation(task, context);
          break;
        case 'content_recommendation':
          result = await this.handleContentRecommendation(task, context);
          break;
        case 'knowledge_refresh':
          result = await this.handleKnowledgeRefresh(task, context);
          break;
        case 'compliance_checking':
          result = await this.handleComplianceChecking(task, context);
          break;
        default:
          throw new Error(`Unsupported capability: ${task.capability}`);
      }

      const executionTime = Date.now() - startTime;

      return {
        taskId: task.id,
        agentId: this.id,
        status: 'completed',
        result: {
          data: result,
          confidence: 0.94,
          reasoning: `Successfully executed ${task.capability} with high confidence`
        },
        metrics: {
          executionTime,
          tokensUsed: 0,
          costUSD: this.costPerCall,
          retryCount: 0,
          cacheHit: false
        },
        timestamp: Date.now()
      };
    } catch (error: any) {
      this.logger.error(`Company knowledge agent execution failed: ${task.capability}`, error, {
        correlationId: context.correlationId
      });

      return {
        taskId: task.id,
        agentId: this.id,
        status: 'failed',
        error: {
          code: 'EXECUTION_FAILED',
          message: error.message,
          details: { capability: task.capability },
          retryable: true,
          category: 'system' as const
        },
        metrics: {
          executionTime: Date.now() - startTime,
          tokensUsed: 0,
          costUSD: 0,
          retryCount: 0,
          cacheHit: false
        },
        timestamp: Date.now()
      };
    }
  }

  // ============================================================================
  // CAPABILITY 1: WEBSITE SCRAPING
  // ============================================================================

  private async handleWebsiteScraping(
    task: AgentTask,
    context: BusinessContext
  ): Promise<any> {
    const { url, maxDepth = 3, maxPages = 100 } = task.input.data as any as any;

    this.logger.info('Starting website scraping', {
      url,
      maxDepth,
      businessId: context.businessId
    });

    // Check robots.txt first
    const robotsAllowed = await this.checkRobotsTxt(url);
    if (!robotsAllowed) {
      return {
        success: false,
        error: 'Scraping not allowed by robots.txt',
        pagesScraped: 0
      };
    }

    // Get or create knowledge source
    const sourceId = await this.getOrCreateKnowledgeSource(
      context.businessId,
      url,
      'website'
    );

    // Perform crawling
    const scrapedPages: WebScrapeResult[] = [];
    const visitedUrls = new Set<string>();
    const urlQueue: Array<{ url: string; depth: number }> = [{ url, depth: 0 }];

    while (urlQueue.length > 0 && scrapedPages.length < maxPages) {
      const current = urlQueue.shift();
      if (!current) break;

      if (visitedUrls.has(current.url) || current.depth > maxDepth) {
        continue;
      }

      // Respect rate limits
      await this.respectRateLimit();

      // Scrape page
      const scrapeResult = await this.scrapePage(current.url);

      if (scrapeResult.success) {
        scrapedPages.push(scrapeResult);
        visitedUrls.add(current.url);

        // Store in knowledge base
        await this.storeScrapedContent(
          context.businessId,
          sourceId,
          scrapeResult
        );

        // Add links to queue
        if (current.depth < maxDepth) {
          for (const link of scrapeResult.links) {
            if (!visitedUrls.has(link) && this.isSameDomain(url, link)) {
              urlQueue.push({ url: link, depth: current.depth + 1 });
            }
          }
        }
      }
    }

    // Update source statistics
    await this.updateSourceStatistics(sourceId, scrapedPages.length);

    // Trigger brand voice analysis if this is first scrape
    if (scrapedPages.length > 5) {
      await this.analyzeBrandVoiceFromPages(context.businessId, scrapedPages);
    }

    return {
      success: true,
      pagesScraped: scrapedPages.length,
      sourceId,
      summary: `Successfully scraped ${scrapedPages.length} pages from ${url}`,
      nextSteps: [
        'Analyze brand voice',
        'Extract product information',
        'Generate FAQs',
        'Set up automatic refresh'
      ]
    };
  }

  private async checkRobotsTxt(url: string): Promise<boolean> {
    try {
      const baseUrl = new URL(url);
      const robotsUrl = `${baseUrl.protocol}//${baseUrl.host}/robots.txt`;

      const response = await fetch(robotsUrl);
      if (!response.ok) return true; // No robots.txt = allowed

      const robotsTxt = await response.text();

      // Simple check - in production, use proper robots.txt parser
      if (robotsTxt.includes('User-agent: *') && robotsTxt.includes('Disallow: /')) {
        return false;
      }

      return true;
    } catch (error) {
      // If can't fetch robots.txt, assume allowed
      return true;
    }
  }

  private async respectRateLimit(): Promise<void> {
    const now = Date.now();
    const timeSinceLastScrape = now - this.lastScrapeTime;

    if (timeSinceLastScrape < this.scrapeDelay) {
      await new Promise(resolve => setTimeout(resolve, this.scrapeDelay - timeSinceLastScrape));
    }

    this.lastScrapeTime = Date.now();
  }

  private async scrapePage(url: string): Promise<WebScrapeResult> {
    try {
      const response = await fetch(url, {
        headers: {
          'User-Agent': 'CoreFlow360-Bot/1.0 (Learning Agent; +https://coreflow360.com/bot)',
          'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
        }
      });

      if (!response.ok) {
        return {
          url,
          title: '',
          content: '',
          links: [],
          metadata: {},
          scrapedAt: new Date().toISOString(),
          success: false,
          error: `HTTP ${response.status}`
        };
      }

      const html = await response.text();

      // Extract content
      const extracted = this.extractContentFromHTML(html, url);

      return {
        url,
        ...extracted,
        scrapedAt: new Date().toISOString(),
        success: true
      };
    } catch (error: any) {
      return {
        url,
        title: '',
        content: '',
        links: [],
        metadata: {},
        scrapedAt: new Date().toISOString(),
        success: false,
        error: error.message
      };
    }
  }

  private extractContentFromHTML(
    html: string,
    baseUrl: string
  ): {
    title: string;
    content: string;
    links: string[];
    metadata: Record<string, string>;
  } {
    // Simplified extraction - use proper HTML parser in production
    const title = this.extractBetween(html, '<title>', '</title>').trim();

    // Extract main content (simplified)
    let content = html;

    // Remove scripts and styles
    content = content.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
    content = content.replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '');

    // Remove HTML tags
    content = content.replace(/<[^>]+>/g, ' ');

    // Clean up whitespace
    content = content.replace(/\s+/g, ' ').trim();

    // Extract meta description
    const description = this.extractBetween(
      html,
      'name="description" content="',
      '"'
    );

    // Extract links
    const links = this.extractLinks(html, baseUrl);

    return {
      title: title || 'Untitled',
      content: content.slice(0, 10000), // Limit content length
      links: links.slice(0, 50), // Limit links
      metadata: {
        description,
        url: baseUrl
      }
    };
  }

  private extractBetween(text: string, start: string, end: string): string {
    const startIndex = text.indexOf(start);
    if (startIndex === -1) return '';

    const contentStart = startIndex + start.length;
    const endIndex = text.indexOf(end, contentStart);
    if (endIndex === -1) return '';

    return text.slice(contentStart, endIndex);
  }

  private extractLinks(html: string, baseUrl: string): string[] {
    const links: string[] = [];
    const hrefRegex = /href=["']([^"']+)["']/gi;
    let match;

    while ((match = hrefRegex.exec(html)) !== null) {
      try {
        const link = new URL(match[1], baseUrl).href;
        if (link.startsWith('http')) {
          links.push(link);
        }
      } catch (error) {
        // Invalid URL, skip
      }
    }

    return Array.from(new Set(links)); // Remove duplicates
  }

  private isSameDomain(baseUrl: string, link: string): boolean {
    try {
      const base = new URL(baseUrl);
      const target = new URL(link);
      return base.host === target.host;
    } catch (error) {
      return false;
    }
  }

  private async storeScrapedContent(
    businessId: string,
    sourceId: string,
    scrapeResult: WebScrapeResult
  ): Promise<void> {
    // Determine content type from URL and content
    const contentType = this.classifyContent(scrapeResult.url, scrapeResult.content);

    // Generate summary
    const summary = scrapeResult.content.slice(0, 200) + '...';

    // Extract keywords
    const keywords = this.extractKeywords(scrapeResult.content);

    // Generate embeddings for semantic search
    let embedding: number[] | null = null;
    if (this.vectorizeIndex && this.openaiApiKey) {
      embedding = await this.generateEmbedding(scrapeResult.content);
    }

    // Store in database
    await this.db
      .prepare(`
        INSERT INTO company_knowledge_base (
          id, business_id, content_type, title, content, summary,
          keywords, source_url, source_id, scrape_date,
          language, word_count, status, freshness_score
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'en', ?, 'active', 1.0)
      `)
      .bind(
        CorrelationId.generate(),
        businessId,
        contentType,
        scrapeResult.title,
        scrapeResult.content,
        summary,
        JSON.stringify(keywords),
        scrapeResult.url,
        sourceId,
        scrapeResult.scrapedAt,
        scrapeResult.content.split(/\s+/).length
      )
      .run();

    // Store embeddings in Vectorize if available
    if (embedding && this.vectorizeIndex) {
      try {
        await this.vectorizeIndex.insert([
          {
            id: CorrelationId.generate(),
            values: embedding,
            namespace: businessId,
            metadata: {
              url: scrapeResult.url,
              title: scrapeResult.title,
              contentType
            }
          }
        ]);
      } catch (error) {
        this.logger.error('Failed to store embeddings', error);
      }
    }
  }

  private classifyContent(url: string, content: string): string {
    const urlLower = url.toLowerCase();
    const contentLower = content.toLowerCase();

    if (urlLower.includes('/product') || contentLower.includes('buy now')) {
      return 'product';
    }
    if (urlLower.includes('/pricing') || contentLower.includes('price') || contentLower.includes('$')) {
      return 'pricing';
    }
    if (urlLower.includes('/faq') || contentLower.includes('frequently asked')) {
      return 'faq';
    }
    if (urlLower.includes('/blog')) {
      return 'blog_post';
    }
    if (urlLower.includes('/policy') || urlLower.includes('/terms')) {
      return 'policy';
    }
    if (urlLower.includes('/about')) {
      return 'about_us';
    }
    if (urlLower.includes('/docs') || urlLower.includes('/documentation')) {
      return 'documentation';
    }

    return 'other';
  }

  private extractKeywords(content: string, limit: number = 20): string[] {
    // Simple keyword extraction (use NLP in production)
    const words = content.toLowerCase().match(/\b\w{4,}\b/g) || [];
    const wordFreq = new Map<string, number>();

    // Common stop words to filter
    const stopWords = new Set([
      'this',
      'that',
      'with',
      'from',
      'have',
      'been',
      'will',
      'your',
      'more',
      'about',
      'into',
      'than',
      'them',
      'some',
      'would',
      'make',
      'like',
      'what',
      'which',
      'their'
    ]);

    for (const word of words) {
      if (!stopWords.has(word)) {
        wordFreq.set(word, (wordFreq.get(word) || 0) + 1);
      }
    }

    return Array.from(wordFreq.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit)
      .map(([word]) => word);
  }

  private async generateEmbedding(text: string): Promise<number[]> {
    if (!this.openaiApiKey) {
      return this.generateFallbackEmbedding(text);
    }

    try {
      const response = await fetch('https://api.openai.com/v1/embeddings', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${this.openaiApiKey}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: 'text-embedding-3-small',
          input: text.slice(0, 8000),
          encoding_format: 'float'
        })
      });

      if (!response.ok) {
        return this.generateFallbackEmbedding(text);
      }

      const data = (await response.json()) as { data: Array<{ embedding: number[] }> };
      return data.data[0].embedding;
    } catch (error) {
      return this.generateFallbackEmbedding(text);
    }
  }

  private generateFallbackEmbedding(text: string): number[] {
    const dimensions = 1536;
    const embedding = new Array(dimensions);

    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      hash = (hash << 5) - hash + text.charCodeAt(i);
      hash = hash & hash;
    }

    for (let i = 0; i < dimensions; i++) {
      hash = (hash * 1664525 + 1013904223) & 0xffffffff;
      embedding[i] = (hash / 0xffffffff) * 2 - 1;
    }

    return embedding;
  }

