  try {
    const request: MigrationRequest = await c.req.json();
    const env = c.env;

    // GRUG: MigrationTester doesn't have validateMigrationRequest - create manual validation
    const validation: ValidationResult = {
      isValid: true,
      errors: []
    };

    // Basic validation
    if (!request.sourceConfig || !request.targetConfig) {
      validation.isValid = false;
      validation.errors = ['Source and target configurations are required'];
    }

    if (!validation.isValid) {
      return c.json({
        success: false,
        errors: validation.errors
      }, 400);
    }

    // Create migration ID
    const migrationId = crypto.randomUUID();

    // Store migration request
    const migrationData = {
      id: migrationId,
      request,
      status: 'pending',
      createdAt: new Date().toISOString(),
      createdBy: c.get('user')?.id || 'system'
    };

    if (env.MIGRATION_KV) {
      await env.MIGRATION_KV.put(
        `migration:${migrationId}`,
        JSON.stringify(migrationData)
      );
    }

    return c.json({
      success: true,
      migrationId,
      validation
    });
  } catch (error: any) {
    return c.json({
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error'
    }, 400);
  }
});

