  AnsweredBy: z.string().optional(),
  MachineDetectionDuration: z.string().optional()
});

export function createVoiceAgentRoutes(
  voiceAgentConfig: VoiceAgentConfig,
  orchestratorConfig: CallOrchestratorConfig
): Hono {
  const app = new Hono();

  // CORS middleware
  app.use('*', cors({
    origin: ['http://localhost:3000', 'https://*.cloudflare.workers.dev'],
    allowMethods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowHeaders: ['Content-Type', 'Authorization', 'X-Requested-With']
  }));

  // Initialize services
  let voiceAgent: AIVoiceAgent;
  let callOrchestrator: CallOrchestrator;
  let analyticsService: CallAnalyticsService;
  let crmService: CRMService;

  // Middleware to initialize services
  app.use('*', async (c: Context, next) => {
    if (!voiceAgent) {
      crmService = new CRMService(c.env);
      voiceAgent = new AIVoiceAgent(voiceAgentConfig);
      callOrchestrator = new CallOrchestrator(voiceAgentConfig, orchestratorConfig, crmService);
      analyticsService = new CallAnalyticsService();
    }
    await next();
  });

  // Health check
  app.get('/health', (c: Context) => {
    return c.json({
      status: 'healthy',
      service: 'voice-agent',
      timestamp: new Date().toISOString()
    });
  });

  // Initiate single call
  app.post('/calls/initiate',
    zValidator('json', CallInitiationSchema),
    async (c: Context) => {
      try {
        const body = await c.req.json();
        const request = CallInitiationSchema.parse(body) as CallInitiationRequest;

        // Get lead data
        const leadResponse = await crmService.getLead(request.lead_id);
        if (!leadResponse.success || !leadResponse.data) {
          return c.json({
            success: false,
            error: 'Lead not found'
          }, 404);
        }

        // Initiate call directly through orchestrator
        const result = await callOrchestrator.initiateCall(request);

        if (result.status !== 'failed') {
          return c.json({
            success: true,
            message: 'Call initiated successfully',
            call_id: result.call_id,
            status: result.status
          });
        } else {
          return c.json({
            success: false,
            error: 'Call initiation failed'
          }, 400);
        }

      } catch (error: any) {
        return c.json({
          success: false,
          error: 'Internal server error'
        }, 500);
      }
    }
  );

  // Initiate bulk calls
  app.post('/calls/bulk',
    zValidator('json', BulkCallSchema),
    async (c: Context) => {
      try {
        const body = await c.req.json();
        const requestData = BulkCallSchema.parse(body);
        const results: Array<{ lead_id: string; success: boolean; call_id?: string; error?: string }> = [];

        for (let i = 0; i < requestData.lead_ids.length; i++) {
          const leadId = requestData.lead_ids[i];

          // Get lead data
          const leadResponse = await crmService.getLead(leadId);
          if (!leadResponse.success || !leadResponse.data) {
            results.push({
              lead_id: leadId,
              success: false,
              error: 'Lead not found'
            });
            continue;
          }

          // Calculate staggered schedule time
          const scheduledAt = requestData.scheduled_at
            ? new Date(new Date(requestData.scheduled_at).getTime() + i * requestData.stagger_delay_minutes * 60000)
            : new Date(Date.now() + i * requestData.stagger_delay_minutes * 60000);

          // Initiate call
          const result = await callOrchestrator.initiateCall({
            lead_id: leadId,
            priority: requestData.priority,
            call_type: requestData.call_type,
            scheduled_at: scheduledAt.toISOString()
          });

          results.push({
            lead_id: leadId,
            success: result.status !== 'failed',
            call_id: result.call_id
          });
        }

        const successCount = results.filter(r => r.success).length;

        return c.json({
          success: true,
          message: `Queued ${successCount}/${requestData.lead_ids.length} calls`,
          results
        });

      } catch (error: any) {
        return c.json({
          success: false,
          error: 'Internal server error'
        }, 500);
      }
    }
  );

  // Get call result
  app.get('/calls/:callId/result', async (c: Context) => {
    try {
      const callId = c.req.param('callId');
      const result = await voiceAgent.getCallResult(callId);

      if (!result) {
        return c.json({
          success: false,
          error: 'Call result not found'
        }, 404);
      }

      return c.json({
        success: true,
        data: result
      });

    } catch (error: any) {
      return c.json({
        success: false,
        error: 'Internal server error'
      }, 500);
    }
  });

  // Get real-time call state
  app.get('/calls/:callId/state', async (c: Context) => {
    try {
      const callId = c.req.param('callId');
      const state = await voiceAgent.getActiveCallState(callId);

      if (!state) {
