          error: 'Internal server error'
        }, 500);
      }
    }
  );

  app.get('/analytics/calls/:callId', async (c: Context) => {
    try {
      const callId = c.req.param('callId');

      const [analytics, insights] = await Promise.all([
        analyticsService.getCallAnalytics(callId),
