        content: 'Mock decisions made during the call.',
        order: 3
      },
      {
        id: 'next_steps',
        title: 'Next Steps',
        content: analysis.nextSteps.identified.join('\n• '),
        order: 4
      }
    ];
  }

  private extractKeyPoints(analysis: ConversationAnalysis): string[] {
    return analysis.insights.keyInsights;
  }

  private extractActionItems(analysis: ConversationAnalysis): Array<{
    id: string;
    description: string;
    assignee: string;
    dueDate: string;
    priority: 'low' | 'medium' | 'high';
  }> {
    return analysis.nextSteps.identified.map((step: any, index: any) => ({
      id: `action_${index}`,
      description: step,
      assignee: 'TBD',
      dueDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      priority: 'medium' as const
    }));
  }

  private analyzeSentiment(analysis: ConversationAnalysis): {
    overall: 'positive' | 'neutral' | 'negative';
    confidence: number;
    keyMoments: Array<{
      timestamp: string;
      sentiment: string;
      description: string;
    }>;
  } {
    return {
      overall: analysis.sentiment.overall.primary as 'positive' | 'neutral' | 'negative',
      confidence: analysis.sentiment.overall.confidence,
      keyMoments: analysis.sentiment.keyMoments.map((moment: any) => ({
        timestamp: moment.timestamp,
        sentiment: moment.sentiment || 'neutral',
        description: moment.description || 'Key moment'
      }))
    };
  }

  async generateQuickSummary(call: Call): Promise<string> {
    try {
      const sanitizedTranscript = call.transcript.segments
        .map((s: any) => `${s.speaker}: ${s.text}`)
        .join('\n')
        .substring(0, 1000); // Limit for quick summary

      const prompt = createSecureAIPrompt(`
      void prompt;
        Provide a brief 2-3 sentence summary of this call:

        ${sanitizedTranscript}
      `, );

      // Mock quick summary - would use real AI in production
      return `Call with ${call.participants.length} participants discussing ${call.duration} minutes. Key topics included pricing and features. Next steps: schedule demo.`;

    } catch (error: any) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      logger.error('Failed to generate quick summary:', errorMessage);
      return 'Summary generation failed';
    }
  }

  async generateActionItems(call: Call): Promise<Array<{
    id: string;
    description: string;
    assignee: string;
    dueDate: string;
    priority: 'low' | 'medium' | 'high';
    status: 'pending' | 'in_progress' | 'completed';
  }>> {
    try {
      const summary = await this.generateSummary(call);
      return summary.actionItems.map((item: any) => ({
        ...item,
        status: 'pending' as const
      }));
    } catch (error: any) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      logger.error('Failed to generate action items:', errorMessage);
      return [];
    }
  }

  async generateFollowUpEmail(call: Call, lead: Lead): Promise<string> {
    try {
      const summary = await this.generateSummary(call);

      const email = `
Subject: Follow-up on our call - ${lead.company}

Hi ${lead.name},

Thank you for taking the time to speak with me today about ${lead.company}'s needs.

Key points from our discussion:
${summary.keyPoints.map((point: any) => `• ${point}`).join('\n')}

Next steps:
${summary.actionItems.map((item: any) => `• ${item.description}`).join('\n')}

I'll follow up with you ${summary.actionItems[0]?.dueDate ? `by ${new Date(summary.actionItems[0].dueDate).toLocaleDateString()}` : 'soon'}.

Best regards,
[Your Name]
      `;

      return email.trim();
    } catch (error: any) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      logger.error('Failed to generate follow-up email:', errorMessage);
      return 'Follow-up email generation failed';
    }
  }

  async getSummaryById(callId: string): Promise<CallSummary | null> {
    const cacheKey = `summary_${callId}`;
    return this.summaryCache.get(cacheKey) || null;
  }

  async updateSummary(callId: string, updates: Partial<CallSummary>): Promise<CallSummary | null> {
    const cacheKey = `summary_${callId}`;
    const existing = this.summaryCache.get(cacheKey);

    if (!existing) {
      return null;
    }

    const updated = { ...existing, ...updates };
    this.summaryCache.set(cacheKey, updated);
    return updated;
  }

  async deleteSummary(callId: string): Promise<boolean> {
    const cacheKey = `summary_${callId}`;
    return this.summaryCache.delete(cacheKey);
  }

  async getSummaryStats(): Promise<{
    totalSummaries: number;
    averageConfidence: number;
    mostCommonSentiment: string;
    averageActionItems: number;
  }> {
    const summaries = Array.from(this.summaryCache.values());

    if (summaries.length === 0) {
      return {
        totalSummaries: 0,
        averageConfidence: 0,
        mostCommonSentiment: 'neutral',
        averageActionItems: 0
      };
    }

    const totalConfidence = summaries.reduce((sum, s) => sum + s.confidence, 0);
    const sentimentCounts: Record<string, number> = {};
    const totalActionItems = summaries.reduce((sum, s) => sum + s.actionItems.length, 0);

    summaries.forEach((summary: any) => {
      const sentiment = summary.sentiment.overall;
      sentimentCounts[sentiment] = (sentimentCounts[sentiment] || 0) + 1;
    });

    const mostCommonSentiment = Object.entries(sentimentCounts)
      .sort(([,a], [,b]) => b - a)[0]?.[0] || 'neutral';

    return {
      totalSummaries: summaries.length,
      averageConfidence: totalConfidence / summaries.length,
      mostCommonSentiment,
      averageActionItems: totalActionItems / summaries.length
    };
  }

  async clearCache(): Promise<void> {
    this.summaryCache.clear();
  }

  async healthCheck(): Promise<{ status: string; timestamp: string }> {
    try {
      return {
        status: 'healthy',
        timestamp: new Date().toISOString()
      };
    } catch (error: any) {
      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString()
      };
    }
  }
}

import { BaseIntegration } from './base-integration';

import type { SyncResult } from '../../types/integration';

// =====================================================
// META ADS INTEGRATION
// =====================================================

export class MetaAdsIntegration extends BaseIntegration {
  private baseUrl = 'https://graph.facebook.com/v18.0';

  async connect(): Promise<boolean> {
    try {
      const testUrl = `${this.baseUrl}/me?access_token=${this.integration.config.accessToken}`;
      const response = await this.makeApiRequest(testUrl);
      return response.id !== undefined;
    } catch (error: any) {
      return false;
    }
  }

  async disconnect(): Promise<void> {
    this.isConnected = false;
    await this.updateStatus('disconnected');
  }

  async testConnection(): Promise<boolean> {
    return await this.connect();
  }

  async sync(): Promise<SyncResult> {
    const startTime = new Date().toISOString();
    const errors: any[] = [];
    let recordsSynced = 0;
    let recordsFailed = 0;

    try {
      await this.updateStatus('syncing');

      // Sync leads from Meta
      const leads = await this.fetchMetaLeads();

      for (const lead of leads) {
        try {
          await this.syncLeadToCRM(lead);
          recordsSynced++;
        } catch (error: any) {
          errors.push(this.createSyncError(lead.id, error));
          recordsFailed++;
        }
      }

      await this.updateStatus('connected');
      await this.updateLastSync();

      return {
        integrationId: this.integration.id,
        status: errors.length === 0 ? 'success' : 'partial',
        recordsSynced,
        recordsFailed,
        errors,
        startTime,
        endTime: new Date().toISOString(),
        duration: Date.now() - new Date(startTime).getTime()
      };
    } catch (error: any) {
      await this.updateStatus('error');
      throw error;
    }
  }

  async syncInbound(): Promise<SyncResult> {
    return await this.sync();
  }

  async syncOutbound(): Promise<SyncResult> {
    // Push CRM data to Meta (custom audiences, conversions, etc.)
    const startTime = new Date().toISOString();

    try {
      await this.updateStatus('syncing');

      // Sync conversions to Meta
      const conversions = await this.getRecentConversions();
      await this.pushConversionsToMeta(conversions);

      // Update custom audiences
      const audiences = await this.getCustomAudiences();
      await this.updateMetaAudiences(audiences);

      await this.updateStatus('connected');

      return {
        integrationId: this.integration.id,
        status: 'success',
        recordsSynced: conversions.length + audiences.length,
        recordsFailed: 0,
        startTime,
        endTime: new Date().toISOString(),
        duration: Date.now() - new Date(startTime).getTime()
      };
    } catch (error: any) {
      await this.updateStatus('error');
      throw error;
    }
  }

  getWebhookUrl(): string {
    return `https://api.coreflow360.com/webhooks/meta/${this.integration.id}`;
  }

  private async fetchMetaLeads(): Promise<any[]> {
    const formId = this.integration.config.options?.formId;
    if (!formId) return [];

    const url = `${this.baseUrl}/${formId}/leads?access_token=${this.integration.config.accessToken}`;
    const response = await this.makeApiRequest(url);

    return response.data || [];
  }

  private async syncLeadToCRM(metaLead: any): Promise<void> {
    const mappedData = await this.applyFieldMappings(metaLead);

    const db = this.env.DB_CRM;
    if (!db) throw new Error('Database not available');
    await db.prepare(`
      INSERT OR REPLACE INTO leads (
        id, business_id, first_name, last_name, email, phone,
        source, source_id, metadata, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      `meta_${metaLead.id}`,
      this.integration.config.options?.businessId,
      mappedData.first_name,
      mappedData.last_name,
      mappedData.email,
      mappedData.phone,
      'meta_ads',
      metaLead.id,
      JSON.stringify(metaLead),
      metaLead.created_time || new Date().toISOString()
    ).run();
  }

  private async getRecentConversions(): Promise<any[]> {
    // Get conversions from CRM to push to Meta
    const db = this.env.DB_CRM;
    if (!db) throw new Error('Database not available');
    const conversions = await db.prepare(`
      SELECT * FROM opportunities
      WHERE status = 'closed_won'
        AND close_date >= datetime('now', '-7 days')
        AND metadata->>'$.synced_to_meta' IS NULL
    `).all();

    return conversions.results;
  }

  private async pushConversionsToMeta(conversions: any[]): Promise<void> {
    // Push conversion events to Meta Conversions API
    for (const conversion of conversions) {
      const event = {
        event_name: 'Purchase',
        event_time: Math.floor(new Date(conversion.close_date).getTime() / 1000),
        user_data: {
          em: conversion.email_hash, // Hashed email
          ph: conversion.phone_hash  // Hashed phone
        },
        custom_data: {
          currency: 'USD',
          value: conversion.value
        },
        event_source_url: 'https://coreflow360.com'
      };

      await this.makeApiRequest(
        `${this.baseUrl}/${this.integration.config.options?.pixelId}/events`,
        'POST',
        { data: [event] },
        { 'Authorization': `Bearer ${this.integration.config.accessToken}` }
      );
    }
  }

  private async getCustomAudiences(): Promise<any[]> {
    const db = this.env.DB_CRM;
    if (!db) throw new Error('Database not available');
    const segments = await db.prepare(`
      SELECT * FROM customer_segments
      WHERE active = 1
        AND metadata->>'$.sync_to_meta' = 'true'
    `).all();

    return segments.results;
  }

  private async updateMetaAudiences(audiences: any[]): Promise<void> {
    // Update custom audiences in Meta
    for (const audience of audiences) {
      const audienceId = audience.metadata?.meta_audience_id;
      if (!audienceId) continue;

      // Get leads for this segment
      const leads = await this.getLeadsForSegment(audience.id);

      // Update audience in Meta
      await this.makeApiRequest(
        `${this.baseUrl}/${audienceId}/users`,
        'POST',
        {
          schema: ['EMAIL', 'PHONE'],
          data: leads.map((l: any) => [l.email_hash, l.phone_hash])
        },
        { 'Authorization': `Bearer ${this.integration.config.accessToken}` }
      );
    }
  }

  private async getLeadsForSegment(segmentId: string): Promise<any[]> {
    const db = this.env.DB_CRM;
    if (!db) throw new Error('Database not available');
    const leads = await db.prepare(`
      SELECT * FROM leads
      WHERE segment_id = ?
        AND status = 'qualified'
    `).bind(segmentId).all();

    return leads.results;
  }
}

